-- Trade Checker 테스트 데이터 (실서비스 모드용) — tools/make-seed.mjs 로 만든 파일입니다.
-- 모든 회사는 가상 데이터입니다. (DATA_PROVIDER=sample 상태에서 '다시 확인'까지 동작)
--
-- 사용법
--   1) 사이트에서 테스트 계정으로 회원가입하고 인증 메일 링크를 누릅니다.
--      팀 기능까지 보려면 두 번째 계정(팀원용)도 가입합니다. (없으면 비워 두세요)
--   2) 아래 v_email, v_member_email 을 바꿉니다.
--   3) Supabase → SQL Editor 에 붙여 넣고 Run. (migrations 0001~0004 를 먼저 실행해 두어야 합니다)
-- 다시 실행하면 이 스크립트가 넣은 데이터만 지우고 새로 넣습니다.
--
-- 넣는 내용
--   계정 1 (소유자): Team 유료 요금제 25일 남음 · 이번 주기 12/150건 사용 · 크레딧 12건
--                    조회 기록 8건 (A·B·C·C·D·D·F·F) · 관심 거래처 3곳 (1곳 등급 변동 B→C)
--                    공유 링크 1개 (Warsaw 리포트, 10일 남음) · 결제 내역 5건 (완료 3 · 입금 대기 1 · 환불 1)
--                    보낸 팀 초대 1건 (invitee.test@example.com, 대기 중)
--   계정 2 (팀원):   계정 1의 팀에 합류된 상태 · 조회 기록 3건 · 관심 거래처 1곳

do $$
declare
  v_email text := 'test1@example.com';          -- ← 계정 1 (소유자)
  v_member_email text := '';                     -- ← 계정 2 (팀원). 팀 기능을 안 볼 거면 비워 두세요
  v_uid uuid;
  v_mid uuid;
  v_rep uuid;
  v_ids jsonb := '{}'::jsonb;
  v_token text;
begin
  select id into v_uid from auth.users where lower(email) = lower(v_email);
  if v_uid is null then
    raise exception '% 로 가입된 계정이 없습니다. 사이트에서 먼저 회원가입해 주세요.', v_email;
  end if;
  if coalesce(v_member_email, '') <> '' then
    select id into v_mid from auth.users where lower(email) = lower(v_member_email);
    if v_mid is null then raise exception '% 로 가입된 계정이 없습니다 (팀원용). 비워 두거나 먼저 가입해 주세요.', v_member_email; end if;
    if v_mid = v_uid then raise exception '두 계정은 서로 달라야 합니다.'; end if;
  end if;

  -- 이전 테스트 데이터 정리
  delete from public.watchlist where user_id in (v_uid, v_mid) and company_id in ('sakura-jp','kestrel-nl','nw-global-ae','riyadh-sa','warsaw-pl','lagos-ng','apex-ae','sinoglobal-hk','helvetia-ch','orion-in','sahara-eg');
  delete from public.orders where user_id = v_uid and id like 'TC-TEST-%';
  delete from public.reports where user_id in (v_uid, v_mid) and query like '[테스트]%';
  delete from public.team_invites where owner_id = v_uid and lower(email) in ('invitee.test@example.com', lower(coalesce(v_member_email, '')));

  -- 1. 계정 1: Team 유료 요금제
  insert into public.profiles (id, email) values (v_uid, v_email) on conflict (id) do nothing;
  update public.profiles
     set plan = 'team', plan_expires_at = now() + interval '25 days', is_trial = false, paid_daily_value = 6633.33,
         period_start = current_date - 5, period_used = 12, credits = 12, team_owner = null
   where id = v_uid;

  -- 2. 계정 1 조회 기록 8건
  insert into public.reports (user_id, query, company_id, company_name, country, grade, risk_points, result, created_at)
  values (v_uid, '[테스트] Sakura Precision Trading Co., Ltd.', 'sakura-jp', 'Sakura Precision Trading Co., Ltd.', '일본', 'A', 0, $json${"engineVersion":"2026.10-2","createdAt":"2026-10-19T03:14:29.628Z","dataMode":"샘플 데이터","company":{"id":"sakura-jp","name":"Sakura Precision Trading Co., Ltd.","country":"일본","countryCode":"JP","industry":"정밀부품 유통","city":"Osaka","founded":1987,"regNo":"JP-4120001033218","domain":"sakura-precision.co.jp"},"grade":"A","gradeLabel":"안정","gradeColor":"#1D5BD6","riskPoints":0,"coverage":{"covered":6,"total":6,"items":[{"key":"identity","label":"기업 식별","ok":true},{"key":"sanctions","label":"제재·사기 명단","ok":true},{"key":"customs","label":"통관 실적","ok":true},{"key":"courts","label":"소송","ok":true},{"key":"insolvency","label":"파산·회생","ok":true},{"key":"credit","label":"신용점수","ok":true}],"missing":[],"level":"high"},"capped":null,"thresholds":{"A":8,"B":24,"C":44,"D":69},"summary":"실거래 흔적이 꾸준하고 분쟁·파산 기록이 없습니다.","signals":[{"key":"age","points":0,"group":"기업 식별","label":"설립 연도","value":"1987년 · 39년 차","level":"ok"},{"key":"domain","points":0,"group":"기업 식별","label":"도메인 일치","value":"일치","level":"ok"},{"key":"address","points":0,"group":"기업 식별","label":"등기 주소","value":"확인됨","level":"ok"},{"key":"customs","points":0,"group":"관세 통관","label":"최근 12개월 통관","value":"270건","level":"ok"},{"key":"customs-stale","points":0,"group":"관세 통관","label":"최근 통관일","value":"2일 전","level":"ok"},{"key":"courts-open","points":0,"group":"법적 분쟁","label":"진행 중인 대금 소송","value":"없음","level":"ok"},{"key":"insolvency","points":0,"group":"파산·회생","label":"파산·회생 기록","value":"없음","level":"ok"},{"key":"credit","points":0,"group":"신용평가","label":"신용 점수","value":"88 / 100","level":"ok"},{"key":"fraud","points":0,"group":"무역 사기","label":"사기 신고 이력","value":"없음","level":"ok"}],"customs":{"monthly":[21,19,23,22,20,24,22,25,21,23,26,24],"lastShipmentDaysAgo":2,"topProducts":["반도체 장비 부품","정밀 베어링"],"partnerCountries":["대한민국","대만","독일"],"months":["25.11","25.12","26.01","26.02","26.03","26.04","26.05","26.06","26.07","26.08","26.09","26.10"],"total12m":270},"courts":[],"insolvency":[],"credit":{"score":88,"provider":"샘플 신용평가"},"fraud":[],"guide":{"primary":"TT 후불 수락 가능","terms":["T/T 후불 (B/L 후 30~60일) 수락 가능","첫 거래 금액이 크면 선수금 10~20%를 함께 요청"],"alternatives":["거래가 쌓이면 여신 한도를 단계적으로 늘리세요."],"emailSubject":"Payment terms for our order","emailBody":"Thank you for your order. We are pleased to offer T/T payment within 60 days after the B/L date. Please confirm so we can proceed with production."},"sources":[{"name":"관세 통관 기록","status":"조회됨"},{"name":"현지 법원 기록","status":"조회됨"},{"name":"파산·회생 공고","status":"조회됨"},{"name":"글로벌 신용평가","status":"조회됨"},{"name":"무역 사기 신고 DB","status":"조회됨"}],"disclaimer":"무역 안전 등급은 거래 판단을 돕는 참고 지표이며, 최종 거래 조건은 귀사의 여신 정책에 따라 결정하세요."}$json$::jsonb, now() - interval '1 days')
