,"lastShipmentDaysAgo":19,"topProducts":["생활가전","주방용품"],"partnerCountries":["대한민국","베트남","중국"],"months":["25.11","25.12","26.01","26.02","26.03","26.04","26.05","26.06","26.07","26.08","26.09","26.10"],"total12m":66},"courts":[{"year":2023,"kind":"payment","status":"closed","role":"피고","amountUSD":12500,"court":"Rechtbank Rotterdam (합의 종결)"},{"year":2024,"kind":"contract","status":"closed","role":"원고","amountUSD":8000,"court":"Rechtbank Rotterdam"}],"insolvency":[],"credit":{"score":57,"provider":"샘플 신용평가"},"fraud":[],"guide":{"primary":"선수금 30% + 잔금 TT","terms":["선수금 30% (T/T, 생산 착수 전)","잔금 70% (선적 서류 송부 전 또는 B/L 후 30일 이내)"],"alternatives":["첫 거래는 소량으로 진행한 뒤 조건 완화를 검토하세요.","무역보험(단기수출보험) 인수 가능 여부를 함께 확인하세요."],"emailSubject":"Proposed payment terms","emailBody":"Thank you for your order. For this shipment, we propose 30% advance payment by T/T before production and the remaining 70% by T/T against copy of shipping documents. We look forward to building a long-term partnership."},"sources":[{"name":"관세 통관 기록","status":"조회됨"},{"name":"현지 법원 기록","status":"조회됨"},{"name":"파산·회생 공고","status":"조회됨"},{"name":"글로벌 신용평가","status":"조회됨"},{"name":"무역 사기 신고 DB","status":"조회됨"}],"disclaimer":"무역 안전 등급은 거래 판단을 돕는 참고 지표이며, 최종 거래 조건은 귀사의 여신 정책에 따라 결정하세요."}$json$::jsonb, now() - interval '2 days')
